    "content": "plugins {\n    id(\"com.android.application\")\n    id(\"org.jetbrains.kotlin.android\")\n    id(\"org.jetbrains.kotlin.plugin.compose\")\n}\n\nandroid {\n    namespace = \"app.mozillavpnlite\"\n    compileSdk = 35\n    ndkVersion = \"27.0.12077973\"\n\n    packaging {\n        jniLibs {\n            useLegacyPackaging = true\n        }\n    }\n\n    externalNativeBuild {\n        ndkBuild {\n            path = file(\"../hev-socks5-tunnel/Android.mk\")\n        }\n    }\n\n    defaultConfig {\n        applicationId = \"app.mozillavpnlite\"\n        minSdk = 24\n        targetSdk = 35\n        versionCode = 1\n        versionName = \"1.0.0-lite\"\n\n        ndk {\n            abiFilters += listOf(\"arm64-v8a\", \"armeabi-v7a\")\n        }\n\n        externalNativeBuild {\n            ndkBuild {\n                targets += \"hev-socks5-tunnel\"\n                arguments += listOf(\"REV_ID=2.19.3\", \"APP_SUPPORT_FLEXIBLE_PAGE_SIZES=true\")\n                cFlags += listOf(\"-O3\", \"-DPKGNAME=app/mozillavpnlite\", \"-DCLSNAME=Tun2Socks\")\n            }\n        }\n    }\n\n    buildTypes {\n        release {\n            isMinifyEnabled = false\n            isShrinkResources = false\n            signingConfig = signingConfigs.getByName(\"debug\")\n        }\n    }\n\n    compileOptions {\n        sourceCompatibility = JavaVersion.VERSION_17\n        targetCompatibility = JavaVersion.VERSION_17\n    }\n\n    kotlinOptions {\n        jvmTarget = \"17\"\n    }\n\n    buildFeatures {\n        compose = true\n    }\n}\n\ndependencies {\n    implementation(files(\"libs/core.aar\"))\n    implementation(platform(\"androidx.compose:compose-bom:2024.10.01\"))\n    implementation(\"androidx.activity:activity-compose:1.9.3\")\n    implementation(\"androidx.compose.ui:ui\")\n    implementation(\"androidx.compose.material3:material3\")\n    implementation(\"org.jetbrains.kotlinx:kotlinx-coroutines-android:1.9.0\")\n}\n"
